import{t as e}from"./jsx-runtime-Cx0BB4qO.js";import{F as t}from"./index-BvqYNcBm.js";import{n,t as r}from"./LegalLayout-Dy179z9J.js";var i=e(),a=`24 de setembro de 2026`;function o(){return(0,i.jsxs)(r,{title:`Política de Privacidade`,subtitle:`Como o ${t} trata dados em uma instalação auto-hospedada.`,updatedAt:a,children:[(0,i.jsx)(n,{title:`1. Resumo`,children:(0,i.jsxs)(`p`,{children:[`No `,t,`, os dados ficam na infraestrutura de quem hospeda o sistema — o operador. Este fork não ativa licenças, não envia heartbeat e não faz telemetria para servidores da Evolution Foundation ou dos mantenedores.`]})}),(0,i.jsx)(n,{title:`2. Quais dados o sistema trata`,children:(0,i.jsxs)(`ul`,{className:`list-disc space-y-1 pl-5`,children:[(0,i.jsxs)(`li`,{children:[(0,i.jsx)(`span`,{className:`text-foreground`,children:`Autenticação:`}),` a`,` `,(0,i.jsx)(`code`,{className:`text-foreground`,children:`GLOBAL_API_KEY`}),` configurada no servidor e os tokens por instância. No navegador, a URL da API e a chave usada no login podem ser guardadas no armazenamento local para manter a sessão.`]}),(0,i.jsxs)(`li`,{children:[(0,i.jsx)(`span`,{className:`text-foreground`,children:`Instâncias:`}),` identificadores, nome, estado de conexão, número/JID pareado e metadados de operação.`]}),(0,i.jsxs)(`li`,{children:[(0,i.jsx)(`span`,{className:`text-foreground`,children:`Mensagens e contatos:`}),` quando a persistência está habilitada (`,(0,i.jsx)(`code`,{className:`text-foreground`,children:`DATABASE_SAVE_MESSAGES`}),`), mensagens enviadas e recebidas e metadados de conversa são gravados no banco; logs técnicos registram a operação do serviço.`]})]})}),(0,i.jsx)(n,{title:`3. Onde os dados ficam`,children:(0,i.jsx)(`p`,{children:`Em um banco PostgreSQL e em volumes locais do servidor do operador. Nada disso é enviado aos mantenedores deste fork. Para falar com o WhatsApp, o servidor estabelece conexão direta com a infraestrutura do WhatsApp/Meta, como parte do protocolo.`})}),(0,i.jsx)(n,{title:`4. Finalidades e base legal`,children:(0,i.jsx)(`p`,{children:`Os dados são tratados para operar o serviço: autenticar o acesso, conectar instâncias, enviar e receber mensagens e exibir o painel. O operador, na condição de controlador, deve definir a base legal adequada — por exemplo, execução de contrato, consentimento ou legítimo interesse — conforme a LGPD/GDPR e a legislação local.`})}),(0,i.jsx)(n,{title:`5. Compartilhamento`,children:(0,i.jsx)(`p`,{children:`Não há venda de dados. O compartilhamento ocorre apenas com o WhatsApp/Meta, por ser inerente ao funcionamento do protocolo, e com terceiros que o operador decidir integrar.`})}),(0,i.jsx)(n,{title:`6. Segurança`,children:(0,i.jsxs)(`p`,{children:[`Mantenha a `,(0,i.jsx)(`code`,{className:`text-foreground`,children:`GLOBAL_API_KEY`}),` em segredo, sirva o painel e a API por HTTPS, restrinja o acesso de rede e desative o Swagger público (`,(0,i.jsx)(`code`,{className:`text-foreground`,children:`SWAGGER_ENABLED=false`}),`) em hosts expostos à internet. Essas medidas ficam a cargo do operador.`]})}),(0,i.jsx)(n,{title:`7. Retenção e exclusão`,children:(0,i.jsxs)(`p`,{children:[`As mensagens persistidas são podadas após o período definido em`,` `,(0,i.jsx)(`code`,{className:`text-foreground`,children:`MESSAGE_RETENTION_DAYS`}),` `,`(`,(0,i.jsx)(`code`,{className:`text-foreground`,children:`0`}),` mantém indefinidamente). Instâncias e demais dados podem ser removidos pelo painel ou diretamente no banco pelo operador.`]})}),(0,i.jsx)(n,{title:`8. Direitos do titular`,children:(0,i.jsx)(`p`,{children:`Titulares de dados — por exemplo, contatos que trocam mensagens com as instâncias — devem procurar o operador da instalação para exercer seus direitos. O operador é o controlador e responde pelas solicitações.`})}),(0,i.jsx)(n,{title:`9. Observação`,children:(0,i.jsx)(`p`,{children:`Este texto é um modelo de exemplo para instalações auto-hospedadas. Revise e adapte com apoio jurídico antes de usá-lo em produção.`})})]})}export{o as default};